1	import { describe, expect, it } from "vitest";
2	import type { GameHistoryRepository } from "../../domain/game/ports/GameHistoryRepository";
3	import { GameItemSelectionService } from "../../domain/game/services/GameItemSelectionService";
4	import { SentenceGameItemSource } from "../../domain/game/services/SentenceGameItemSource";
5	import { SymbolGameItemSource } from "../../domain/game/services/SymbolGameItemSource";
6	import { WordGameItemSource } from "../../domain/game/services/WordGameItemSource";
7	import type {
8		GameHistoryEntry,
9		GameItem,
10		GameItemSource,
11		GameRoundConfig,
12		RandomSource,
13	} from "../../domain/game/types";
14	import type { CardRepository } from "../../domain/ports/CardRepository";
15	import { consonants } from "../../domain/script/data/symbols";
16	import { ScriptPropertyCard } from "../../domain/script/entities/ScriptPropertyCard";
17	import { SentenceReviewCard } from "../../domain/sentence/entities/SentenceReviewCard";
18	import type { SentenceEntry } from "../../domain/sentence/types";
19	import type { CardPool } from "../../domain/shared/CardPool";
20	import type { RecallRating } from "../../domain/shared/types";
21	import { SrsSchedule } from "../../domain/srs/value-objects/SrsSchedule";
22	import { VocabCard } from "../../domain/vocabulary/entities/VocabCard";
23	import type { VocabEntry } from "../../domain/vocabulary/types";
24	import { PlayGameUseCase } from "./PlayGameUseCase";
25	
26	const SYMBOLS = consonants.slice(0, 5) as ReadonlyArray<
27		(typeof consonants)[number]
28	>;
29	
30	function scriptCard(symbolCharacter: string, id: string): ScriptPropertyCard {
31		return new ScriptPropertyCard(
32			id,
33			`question ${id}`,
34			`answer ${id}`,
35			[`answer ${id}`],
36			SrsSchedule.initial(),
37			symbolCharacter,
38			"recognition",
39			1,
40			"/audio/card-specific.mp3",
41		);
42	}
43	
44	function sentenceCard(sentenceId: string, id: string): SentenceReviewCard {
45		return new SentenceReviewCard(
46			id,
47			`question ${id}`,
48			`answer ${id}`,
49			[`answer ${id}`],
50			SrsSchedule.initial(),
51			sentenceId,
52			"readingComprehension",
53			undefined,
54		);
55	}
56	
57	function vocabCard(thai: string, id: string): VocabCard {
58		return new VocabCard(
59			id,
60			`question ${id}`,
61			`${thai}`,
62			[`${thai}`],
63			SrsSchedule.initial(),
64			thai,
65			"thaiToEnglish",
66			"/audio/card-specific.mp3",
67		);
68	}
69	
70	interface CardsByPool {
71		readonly script?: readonly ScriptPropertyCard[];
72		readonly sentence?: readonly SentenceReviewCard[];
73		readonly vocab?: readonly VocabCard[];
74	}
75	
76	function repositoryOf(cardsByPool: CardsByPool): CardRepository {
77		return {
78			findById: () => null,
79			findDue: () => [],
80			findAll: (pool: CardPool) => {
81				if (pool === "script") return [...(cardsByPool.script ?? [])];
82				if (pool === "sentence") return [...(cardsByPool.sentence ?? [])];
83				if (pool === "vocab") return [...(cardsByPool.vocab ?? [])];
84				return [];
85			},
86			save: () => {},
87			saveAll: () => {},
88			remove: () => {},
89		};
90	}
91	
92	function fakeHistoryRepository(): GameHistoryRepository & {
93		entries: GameHistoryEntry[];
94	} {
95		const entries: GameHistoryEntry[] = [];
96		return {
97			entries,
98			list: () => ({ status: "ok", entries: [...entries] }),
99			save: (entry) => {
100				entries.push(entry);
101			},
102		};
103	}
104	
105	function scripted(values: readonly number[]): RandomSource {
106		let index = 0;
107		return () => values[index++ % values.length] as number;
108	}
109	
110	const CONFIG: GameRoundConfig = {
111		pools: ["script"],
112		itemCount: 5,
113		prioritizeWeakItems: false,
114		inputMode: "paper",
115	};
116	
117	function setUp(
118		cardsByPool: CardsByPool = {},
119		sourcesFactory?: (repo: CardRepository) => readonly GameItemSource[],
120	) {
121		const cardRepository = repositoryOf(cardsByPool);
122		const sources = sourcesFactory
123			? sourcesFactory(cardRepository)
124			: [new SymbolGameItemSource(cardRepository)];
125		const selectionService = new GameItemSelectionService(
126			sources,
127			cardRepository,
128		);
129		const historyRepository = fakeHistoryRepository();
130		const useCase = new PlayGameUseCase(selectionService, historyRepository);
131		return { cardRepository, selectionService, historyRepository, useCase };
132	}
133	
134	/**
135	 * A round wired over all three pools with one card/entry each — the fixture
136	 * shared by task 1.2's AC1-AC3, which each start from the identical
137	 * three-pool setup and differ only in the round they play.
138	 */
139	function setUpFullyWiredGame() {
140		const symbolCards = SYMBOLS.slice(0, 2).map((symbol, index) =>
141			scriptCard(symbol.character, `card-${index}`),
142		);
143		const sentenceCards = [sentenceCard("sentence-1", "sentence-card-1")];
144		const vocabCards = [vocabCard("มา", "vocab:มา:thaiToEnglish")];
145		const sentenceEntry: SentenceEntry = {
146			id: "sentence-1",
147			thai: "มา กิน",
148			english: "come eat",
149			romanization: "maa gin",
150			words: ["มา", "กิน"],
151			difficulty: 1,
152			thai_audio_file: null,
153			cards: { readingComprehension: { distractors: [] } },
154		} as SentenceEntry;
155		const vocabEntry = {
156			thai: "มา",
157			english: "come",
158			difficulty: 1,
159		} as VocabEntry;
160	
161		return setUp(
162			{ script: symbolCards, sentence: sentenceCards, vocab: vocabCards },
163			(cardRepository) => [
164				new SymbolGameItemSource(cardRepository),
165				new WordGameItemSource(cardRepository, [vocabEntry]),
166				new SentenceGameItemSource(cardRepository, [sentenceEntry]),
167			],
168		);
169	}
170	
171	function rateAll(
172		useCase: PlayGameUseCase,
173		items: readonly GameItem[],
174		ratings: readonly RecallRating[],
175	) {
176		return items.reduce(
177			(acc, _item, index) =>
178				useCase.recordRating(items, acc, index, ratings[index] as RecallRating),
179			[] as ReturnType<PlayGameUseCase["recordRating"]>,
180		);
181	}
182	
183	describe("PlayGameUseCase", () => {
184		it("AC1: starts a round matching what GameItemSelectionService itself would produce", () => {
185			const cards = SYMBOLS.map((symbol, index) =>
186				scriptCard(symbol.character, `card-${index}`),
187			);
188			const { selectionService, useCase } = setUp({ script: cards });
189			const rng1 = scripted([0.1, 0.3, 0.5, 0.7, 0.9, 0.2, 0.4, 0.6, 0.8, 0.05]);
190			const rng2 = scripted([0.1, 0.3, 0.5, 0.7, 0.9, 0.2, 0.4, 0.6, 0.8, 0.05]);
191	
192			const expected = selectionService.selectRound(CONFIG, rng1);
193			const actual = useCase.startRound(CONFIG, rng2);
194	
195			expect(actual).toEqual(expected);
196		});
197	
198		it("AC2: playing a full round leaves every underlying card's schedule untouched", () => {
199			const cards = SYMBOLS.map((symbol, index) =>
200				scriptCard(symbol.character, `card-${index}`),
201			);
202			const { cardRepository, useCase } = setUp({ script: cards });
203			const before = cardRepository
204				.findAll("script")
205				.map((card) => card.schedule.toDTO());
206	
207			const items = useCase.startRound(
208				CONFIG,
209				scripted([0.1, 0.3, 0.5, 0.7, 0.9]),
210			);
211			expect(items).toHaveLength(5);
212	
213			const allRatings: readonly RecallRating[] = [1, 2, 3, 4, 5];
214			const ratings = rateAll(useCase, items, allRatings);
215			const summary = useCase.finishRound(ratings);
216			useCase.saveHistory(CONFIG, summary);
217	
218			const after = cardRepository
219				.findAll("script")
220				.map((card) => card.schedule.toDTO());
221			expect(after).toEqual(before);
222		});
223	
224		it("AC3: reports counts per rating and an integer accuracy rounded half-up", () => {
225			const cards = SYMBOLS.map((symbol, index) =>
226				scriptCard(symbol.character, `card-${index}`),
227			);
228			const { useCase } = setUp({ script: cards });
229			const items = useCase.startRound(
230				CONFIG,
231				scripted([0.1, 0.3, 0.5, 0.7, 0.9]),
232			);
233	
234			const ratings = rateAll(useCase, items, [1, 2, 3, 4, 5]);
235			const summary = useCase.finishRound(ratings);
236	
237			expect(summary.ratingCounts).toEqual({ 1: 1, 2: 1, 3: 1, 4: 1, 5: 1 });
238			expect(summary.ratedCount).toBe(5);
239			// correct = ratings 4,5 -> 2 of 5 = 40%
240			expect(summary.accuracy).toBe(40);
241		});
242	
243		it("AC3b: rounds accuracy half-up on a fractional percentage", () => {
244			const cards = SYMBOLS.slice(0, 3).map((symbol, index) =>
245				scriptCard(symbol.character, `card-${index}`),
246			);
247			const { useCase } = setUp({ script: cards });
248			const config: GameRoundConfig = { ...CONFIG, itemCount: 3 };
249			const items = useCase.startRound(config, scripted([0.1, 0.3, 0.5]));
250	
251			// 2 of 3 correct (Good/Easy) -> 66.666...% -> rounds to 67.
252			const ratings = rateAll(useCase, items, [4, 4, 1]);
253			const summary = useCase.finishRound(ratings);
254	
255			expect(summary.accuracy).toBe(67);
256		});
257	
258		it("AC4: two rounds on the same instance reflect only their own ratings", () => {
259			const cards = SYMBOLS.map((symbol, index) =>
260				scriptCard(symbol.character, `card-${index}`),
261			);
262			const { useCase } = setUp({ script: cards });
263			const config: GameRoundConfig = { ...CONFIG, itemCount: 2 };
264	
265			const itemsA = useCase.startRound(config, scripted([0.1, 0.6]));
266			const ratingsA = rateAll(useCase, itemsA, [1, 1]);
267			const summaryA = useCase.finishRound(ratingsA);
268	
269			const itemsB = useCase.startRound(config, scripted([0.2, 0.7]));
270			const ratingsB = rateAll(useCase, itemsB, [5, 5]);
271			const summaryB = useCase.finishRound(ratingsB);
272	
273			expect(summaryA.accuracy).toBe(0);
274			expect(summaryA.ratingCounts[1]).toBe(2);
275			expect(summaryB.accuracy).toBe(100);
276			expect(summaryB.ratingCounts[5]).toBe(2);
277		});
278	
279		it("AC5: a zero-rating round reports accuracy null, distinct from a rated 0% round", () => {
280			const { useCase } = setUp({});
281	
282			const emptySummary = useCase.finishRound([]);
