1	import type { CardPool } from "../shared/CardPool";
2	import type { RecallRating } from "../shared/types";
3	
4	/**
5	 * The practice game draws only from the pools that hold learnable "items" a
6	 * person can be quizzed on in both directions. It is an `Extract` of
7	 * `CardPool` rather than a separate vocabulary so the two concepts never
8	 * drift apart.
9	 *
10	 * Growing this type does *not* on its own update every place that has to
11	 * know the full set: `StorageGameHistoryRepository`'s persisted-entry shape
12	 * guard derives its allowlist from a `Record<GameCardPool, true>` anchor
13	 * precisely so that adding a member here is a compile error there rather
14	 * than a silently stale duplicate.
15	 */
16	export type GameCardPool = Extract<CardPool, "script" | "vocab" | "sentence">;
17	
18	/** A source of randomness returning a number in `[0, 1)`. */
19	export type RandomSource = () => number;
20	
21	/** Whether the learner writes on the canvas or on paper. */
22	export type GameInputMode = "draw" | "paper";
23	
24	/**
25	 * `dictation` — hear it, write it. `reading` — see it, say it, hear the
26	 * reveal. Which one a given item gets is randomized per round, never
27	 * configured.
28	 */
29	export type SymbolChallengeDirection = "dictation" | "reading";
30	
31	/**
32	 * `dictationTranslate` — hear the Thai word, write the Thai spelling and
33	 * the English meaning. `production` — see the English, write the Thai
34	 * spelling and say it, hear/see the reveal. Which one a given word gets is
35	 * randomized per round, never configured.
36	 */
37	export type WordChallengeDirection = "dictationTranslate" | "production";
38	
39	/**
40	 * `listening` — hear the sentence, reveal the Thai text and its English.
41	 * `reading` — see the Thai text, say it, reveal the audio. Which one a
42	 * given sentence gets is randomized per round, never configured — except
43	 * that a sentence with no audio can only ever be `reading`
44	 * (`assignDirection`). Every sentence in the shipped `sentences.json` is
45	 * audio-less today, so `listening` is currently unreachable in practice;
46	 * it becomes reachable the moment sentence audio exists, with no code
47	 * change. See CONTEXT.md.
48	 */
49	export type SentenceChallengeDirection = "listening" | "reading";
50	
51	/**
52	 * Tone identification is a single self-assessment — did the learner
