1	import type { CardRepository } from "../../ports/CardRepository";
2	import { ScriptPropertyCard } from "../../script/entities/ScriptPropertyCard";
3	import { SentenceReviewCard } from "../../sentence/entities/SentenceReviewCard";
4	import type { ReviewableCard } from "../../srs/entities/ReviewableCard";
5	import { VocabCard } from "../../vocabulary/entities/VocabCard";
6	import type {
7		GameCardPool,
8		GameItem,
9		GameItemContent,
10		GameItemSource,
11		GameRoundConfig,
12		RandomSource,
13		SentenceChallengeDirection,
14		SymbolChallengeDirection,
15		ToneChallengeDirection,
16		WordChallengeDirection,
17	} from "../types";
18	import { itemWeight, type ScheduleStats, worstStats } from "./itemWeight";
19	import { sampleWithoutReplacement } from "./sampling";
20	import type { ToneGameItemSource } from "./ToneGameItemSource";
21	
22	/**
23	 * `selectRound`'s own config shape: `GameRoundConfig`'s `prioritizeWeakItems`
24	 * made optional here (rather than `Pick`, which would keep it required) so
25	 * every caller that predates weighting — every existing test, and any
26	 * caller that never intends to weight — keeps compiling unchanged.
27	 * `includeTonePractice` is already optional on `GameRoundConfig` itself, so
28	 * `Pick` carries it through unchanged.
29	 */
30	type SelectRoundConfig = Pick<
31		GameRoundConfig,
32		"pools" | "itemCount" | "includeTonePractice"
33	> & {
34		readonly prioritizeWeakItems?: boolean;
35	};
36	
37	/**
38	 * Composes one `GameItemSource` per pool, samples across them, and assigns
39	 * each drawn item a challenge direction. Adding a pool is adding a source
40	 * to the array; weighting (task 3.1) is supplying `weightOf` to the sample
41	 * when `prioritizeWeakItems` is set — no other behavior changes.
42	 *
43	 * The optional `toneSource` is consulted separately, whenever
44	 * `config.includeTonePractice` is set, regardless of `config.pools` — tone
45	 * practice is independent of pool selection by design, so it has no honest
46	 * `pool` value and is never one of `sources` (see `ToneGameItemSource`).
47	 * Tone items are never scanned by `weightOfFor` (which only reads cards
48	 * from the requested `pools`), so they always draw at the same neutral
49	 * weight regardless of `prioritizeWeakItems` — a deliberate, tested choice,
50	 * not an oversight.
51	 *
52	 * The optional `cardRepository` is read only for weighting, directly (the
53	 * same `easeFactor`/`lapseCount`/`repetitions` fields
54	 * `ReviewService.getCriticalItems` reads) — never through `ReviewService`
55	 * itself, which stays a sibling over the same port, not something this
56	 * service chains through.
57	 */
58	export class GameItemSelectionService {
59		constructor(
60			private readonly sources: readonly GameItemSource[],
61			private readonly cardRepository?: CardRepository,
62			private readonly toneSource?: ToneGameItemSource,
63		) {}
64	
65		selectRound(
66			config: SelectRoundConfig,
67			rng: RandomSource = Math.random,
68		): GameItem[] {
69			const eligible: GameItemContent[] = this.eligibleContent(config.pools);
70			if (config.includeTonePractice && this.toneSource) {
71				eligible.push(...this.toneSource.eligibleContent());
72			}
73			const weightOf =
74				config.prioritizeWeakItems && this.cardRepository
75					? this.weightOfFor(config.pools)
76					: undefined;
77			const drawn = sampleWithoutReplacement(eligible, config.itemCount, {
78				rng,
79				weightOf,
80			});
81			return drawn.map((content) => assignDirection(content, rng));
82		}
83	
84		private eligibleContent(pools: readonly GameCardPool[]): GameItemContent[] {
85			return this.sources
86				.filter((source) => pools.includes(source.pool))
87				.flatMap((source) => source.eligibleContent());
88		}
89	
90		/**
