102			// share one key (one per PropertyType/VocabProperty), so this collects
103			// them all before `worstStats` below picks the representative one.
104			const statsByKey = new Map<string, ScheduleStats[]>();
105			for (const pool of pools) {
106				for (const card of this.cardRepository?.findAll(pool) ?? []) {
107					const key = itemKeyOfCard(card);
108					if (!key) continue;
109					const stats: ScheduleStats = {
110						easeFactor: card.schedule.easeFactor.value,
111						lapseCount: card.schedule.lapseCount,
112						repetitions: card.schedule.repetitions,
113					};
114					const list = statsByKey.get(key);
115					if (list) list.push(stats);
116					else statsByKey.set(key, [stats]);
117				}
118			}
