120			// One weight per key, from its worst card's stats only.
121			const weightByKey = new Map<string, number>();
122			for (const [key, stats] of statsByKey) {
123				const worst = worstStats(stats);
124				if (worst) weightByKey.set(key, itemWeight(worst));
125			}
